mapper.select:
SELECT e.*, s.name AS storage_name, it.name AS type_name, ut.name AS current_user_name FROM equipment e LEFT JOIN storage s ON e.storage_id = s.id LEFT JOIN itemtype it ON e.type_id = it.id LEFT JOIN usertable ut ON e.current_user_id = ut.id
AND e.name LIKE CONCAT('%', #{name}, '%')
AND e.brand LIKE CONCAT('%', #{brand}, '%')
AND e.status = #{status}
AND e.storage_id = #{storageId}
AND e.current_user_id = #{userId}
ORDER BY e.id DESC

mapper.insert:
