             #{currentUserId}, #{borrowDate}, #{expectedReturnDate}, #{actualReturnDate},
             #{serialNumber}, #{purchaseDate}, #{price}, #{remark}
         )

mapper.select:
SELECT br.id, br.type, br.status, br.apply_time, br.approve_time, ut.name AS user_name, a.name AS reviewer_name, br.borrow_time, br.return_time FROM equipment_borrow_record br LEFT JOIN usertable ut ON br.user_id = ut.id LEFT JOIN admin a ON br.reviewer_id = a.id
br.equip_id = #{equipId}
AND br.apply_time >= #{startTime}
AND br.apply_time <= #{endTime}
ORDER BY br.apply_time DESC

mapper.update:
UPDATE equipment
SET status = #{status},
    current_user_id = #{currentUserId},
    borrow_date = #{borrowDate},
    actual_return_date = #{actualReturnDate}
WHERE id = #{id}
